import io

import numpy as np
import pytest
from PIL import Image

from qc_preprocess import PreprocessParams, load_image, preprocess


def encode(img: Image.Image, fmt: str, **kwargs: object) -> bytes:
    buf = io.BytesIO()
    img.save(buf, fmt, **kwargs)
    return buf.getvalue()


def pattern_image(width: int = 64, height: int = 48) -> Image.Image:
    """Deterministic RGB test image generated by a fixed formula."""
    y, x = np.mgrid[0:height, 0:width]
    arr = np.stack(
        [(x * 7 + y * 3) % 256, (x * y) % 256, (255 - x * 4 + y * 5) % 256], axis=-1
    ).astype(np.uint8)
    return Image.fromarray(arr, "RGB")


def test_shape_dtype_contiguous_and_values_for_solid_color() -> None:
    out = preprocess(Image.new("RGB", (300, 400), (255, 0, 51)))
    assert out.shape == (1, 3, 224, 224)
    assert out.dtype == np.float32
    assert out.flags.c_contiguous
    expected = [2.2489083, -2.0357143, -0.9155556]
    for c, value in enumerate(expected):
        np.testing.assert_allclose(out[0, c], value, atol=0.02)


def _grid_4x4() -> Image.Image:
    arr = np.zeros((4, 4, 3), dtype=np.uint8)
    for y in range(4):
        for x in range(4):
            v = 16 * (4 * y + x)
            arr[y, x] = (v, 255 - v, 128)
    return Image.fromarray(arr, "RGB")


def test_exact_crop_without_resampling() -> None:
    params = PreprocessParams(resize_shorter=4, crop=2, mean=(0.5,) * 3, std=(0.5,) * 3)
    out = preprocess(_grid_4x4(), params)
    assert out.shape == (1, 3, 2, 2)
    expected_r = np.array([[80, 96], [144, 160]]) / 255 * 2 - 1
    np.testing.assert_allclose(out[0, 0], expected_r, atol=1e-6)
    expected_g = (255 - np.array([[80, 96], [144, 160]])) / 255 * 2 - 1
    np.testing.assert_allclose(out[0, 1], expected_g, atol=1e-6)
    np.testing.assert_allclose(out[0, 2], 128 / 255 * 2 - 1, atol=1e-6)


@pytest.mark.parametrize(
    ("size", "resized"),
    [((300, 400), (256, 341)), ((400, 300), (341, 256)), ((256, 256), (256, 256))],
)
def test_resize_target_uses_truncation(size: tuple[int, int], resized: tuple[int, int]) -> None:
    # A non-uniform pattern makes size and crop origin observable: compare with a manual pipeline.
    img = pattern_image(*size)
    manual = img if img.size == resized else img.resize(resized, Image.Resampling.BILINEAR)
    left, top = (resized[0] - 224) // 2, (resized[1] - 224) // 2
    manual = manual.crop((left, top, left + 224, top + 224))
    expected = (np.asarray(manual, dtype=np.float32) / np.float32(255) - 0.5) / 0.25
    params = PreprocessParams(mean=(0.5,) * 3, std=(0.25,) * 3)
    np.testing.assert_array_equal(preprocess(img, params)[0], expected.transpose(2, 0, 1))


def test_deterministic_bit_identical() -> None:
    pattern = pattern_image()
    a = preprocess(pattern)
    b = preprocess(pattern)
    assert a.tobytes() == b.tobytes()
    data = encode(pattern, "PNG")
    c = preprocess(load_image(data))
    d = preprocess(load_image(data))
    assert c.tobytes() == d.tobytes() == a.tobytes()


def test_input_image_is_not_modified() -> None:
    pattern = pattern_image()
    before = pattern.tobytes()
    preprocess(pattern)
    assert pattern.tobytes() == before and pattern.size == (64, 48)


@pytest.mark.parametrize("mode", ["L", "RGBA", "P", "CMYK"])
def test_non_rgb_rejected(mode: str) -> None:
    with pytest.raises(ValueError):
        preprocess(Image.new(mode, (300, 300)))


def test_empty_image_rejected() -> None:
    with pytest.raises(ValueError):
        preprocess(Image.new("RGB", (0, 10)))


def test_non_image_rejected() -> None:
    with pytest.raises(TypeError):
        preprocess(np.zeros((224, 224, 3)))  # type: ignore[arg-type]
